const $=s=>document.querySelector(s);
const projectPaths=['/work/sonor/','/work/vanta-form/','/work/other-realities/','/work/form-digital/'];
const menu=$('#menuDialog');$('#menuOpen')?.addEventListener('click',()=>{menu.showModal();document.body.style.overflow='hidden'});menu?.addEventListener('close',()=>document.body.style.overflow='');document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());menu?.addEventListener('click',e=>{if(e.target===menu){const r=menu.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)menu.close()}});
const practices=[{name:'Brand identities',description:'Distinctive systems built from a clear idea. Strategy, art direction, typography and the details that hold everything together.',image:'assets/sonor.png'},{name:'Photography & stories',description:'Portraits, campaigns and visual stories shaped by light, people and place. Finding a fresh perspective in the familiar.',image:'assets/campaign.png'},{name:'AI & art direction',description:'Creative curiosity, extended. Imagined worlds and visual experiments guided by a human point of view.',image:'assets/ai-art.png'},{name:'Digital experiences',description:'Expressive websites that balance character with clarity. Thoughtful interfaces, responsive systems and purposeful motion.',image:'assets/hero.png'}];
let practice=0;function selectPractice(i,focus=false){practice=i;const p=practices[i];$('#practiceNumber').textContent='0'+(i+1)+' / 04';$('#practiceTitle').textContent=p.name;$('#practiceDescription').textContent=p.description;$('#practiceImage').src='/'+p.image;$('#practiceImage').alt=p.name+' project';document.querySelectorAll('[data-practice]').forEach((b,n)=>{b.setAttribute('aria-selected',String(n===i));b.tabIndex=n===i?0:-1;if(n===i&&focus)b.focus()})}if($('#practiceTitle')){document.querySelectorAll('[data-practice]').forEach(b=>{b.onclick=()=>selectPractice(Number(b.dataset.practice));b.onkeydown=e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();selectPractice((practice+(e.key==='ArrowRight'?1:3))%4,true)}}});selectPractice(0);$('#practiceProject').onclick=()=>location.assign(projectPaths[practice])}
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});let count=0;document.querySelectorAll('[data-category]').forEach(card=>{card.hidden=b.dataset.filter!=='all'&&card.dataset.category!==b.dataset.filter;if(!card.hidden)count++});$('#filterStatus').textContent=count+' project'+(count===1?'':'s')}));
$('#briefForm')?.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);const brief=['CREATIVE PROJECT BRIEF','','Name: '+data.get('name'),'Email: '+data.get('email'),'Discipline: '+data.get('type'),'','PROJECT OVERVIEW',data.get('message'),'','Prepared locally. This brief has not been sent.'].join('\n');const url=URL.createObjectURL(new Blob([brief],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='creative-project-brief.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#briefStatus').textContent='Your brief is ready to save. No message has been sent.'});
const reduced=matchMedia('(prefers-reduced-motion: reduce)');let pending=false;function animate(){pending=false;if(reduced.matches)return;const portrait=$('.portrait-wrap');if(portrait)portrait.style.setProperty('--portrait-y',Math.min(scrollY*.18,180)+'px');const section=$('#work'),track=$('.work-track');if(section&&track&&innerWidth>800){const rect=section.getBoundingClientRect(),distance=section.offsetHeight-innerHeight;const progress=Math.min(1,Math.max(0,-rect.top/Math.max(1,distance)));const max=Math.max(0,track.scrollWidth-innerWidth*.82);track.style.setProperty('--track-x',(-progress*max)+'px')}const about=$('#about'),statement=$('.statement');if(about&&statement)statement.style.setProperty('--statement-y',Math.max(-45,Math.min(45,(about.getBoundingClientRect().top-innerHeight*.3)*.08))+'px')}function schedule(){if(!pending){pending=true;requestAnimationFrame(animate)}}addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule);animate();
